// StorageAdapter: one interface, two backends (Supabase Storage; encrypted server disk).
// Paths are always "{org_id}/{envelope_id}/{name}" and are generated by the server, never taken from a client.

export const BUCKETS = ['originals', 'sealed', 'signatures', 'attachments', 'branding', 'audit-archives'] as const;
export type Bucket = (typeof BUCKETS)[number];
export type Backend = 'supabase' | 'disk';

export type StorageErrorCode = 'BAD_PATH' | 'ALREADY_EXISTS' | 'NOT_FOUND' | 'CORRUPT' | 'IMMUTABLE' | 'BACKEND';

export class StorageError extends Error {
  constructor(
    public readonly code: StorageErrorCode,
    message: string,
  ) {
    super(message);
    this.name = 'StorageError';
  }
}

export interface StorageAdapter {
  readonly backend: Backend;
  /** Insert-only: fails with ALREADY_EXISTS rather than overwrite. */
  put(bucket: Bucket, path: string, data: Uint8Array, opts: { contentType: string }): Promise<void>;
  get(bucket: Bucket, path: string): Promise<Uint8Array>;
  exists(bucket: Bucket, path: string): Promise<boolean>;
  /**
   * Originals can only be removed with draftOnly (the caller has checked the envelope is a draft) or deletionStarted
   * (the owner's deletion was started in the database; for Supabase the database trigger checks it again).
   */
  remove(bucket: Bucket, path: string, opts?: { draftOnly?: boolean; deletionStarted?: boolean }): Promise<void>;
  usageBytes(): Promise<number>;
}

// up to two extensions, for example ".jsonl.gz" (audit archives); every part starts with a letter or digit, so ".." cannot appear
const SEGMENT = /^[A-Za-z0-9][A-Za-z0-9_-]{0,79}(\.[A-Za-z0-9]{1,8}){0,2}$/;

/** Validate a storage path; returns its segments. Throws BAD_PATH for anything unexpected. */
export function checkPath(bucket: string, path: string): string[] {
  if (!(BUCKETS as readonly string[]).includes(bucket)) throw new StorageError('BAD_PATH', 'Unknown storage bucket');
  if (typeof path !== 'string' || path.length === 0 || path.length > 300) throw new StorageError('BAD_PATH', 'Invalid storage path');
  const parts = path.split('/');
  if (parts.length !== 3 || parts.some((s) => !SEGMENT.test(s) || s.includes('..'))) throw new StorageError('BAD_PATH', 'Invalid storage path');
  return parts;
}
